    env: 'online', // 'online' | 'dev'
    devPort: DEFAULT_DEV_PORT,
    // 选中用户会话（virtualLogin 解析出的 origin + token）
    selectedUser: null,
    loadingSession: false,
    // 按学生 / 班级查询关联教师
